def find(parent, i):
	if parent[i] == i:
		return i
	parent[i] = find(parent, parent[i])
	return parent[i]

def union(parent, rank, x, y):
	rootx = find(parent, x)
	rooty = find(parent, y)
	if rootx != rooty:
		if rank[rootx] < rank[rooty]:
			parent[rootx] = rooty
		elif rank[rootx] > rank[rooty]:
			parent[rooty] = rootx
		else:
			parent[rooty] = rootx
			rank[rootx] += 1
